head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > removeCellClass]<br/>setCellClass() 메소드로 설정한 특정 날짜의 CSS 클래스를 제거합니다.",
    "validation" : [
        "date(필수) 파라미터로 setCellClass() 메소드로 설정한 CSS 클래스를 제거할 날짜를 'yyyyMMdd' 포맷 문자열로 설정합니다.",        
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // comp 생성 함수 호출 (createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 표시월: 2025-11)
    await $c.gcm.createBasicCalendar();
}



// setCellClass 사전 설정
// 여러 날짜에 tmpColor01 / tmpColor02 클래스 설정 후 DOM 카운트 출력
scwin.btn_setCellClass_onclick = function (e) {
    target1.setCellClass("20251115", "tmpColor01");
    target1.setCellClass("20251120", "tmpColor01");
    target1.setCellClass("20251125", "tmpColor02");

    let tmpColor01Count = target1.render.querySelectorAll('.tmpColor01').length;
    let tmpColor02Count = target1.render.querySelectorAll('.tmpColor02').length;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[setCellClass 후 tmpColor01 적용 셀 개수] " + tmpColor01Count + "개"
        + " / [setCellClass 후 tmpColor02 적용 셀 개수] " + tmpColor02Count + "개"
    );
};



// removeCellClass 호출 → 특정 날짜 1개의 CSS 클래스만 제거
// validation:
//  - date(필수): 'yyyyMMdd' 포맷 String
//  - 모든 날짜 일괄 제거는 removeAllCellClass() 사용
scwin.btn_removeCellClass_onclick = function (e) {
    // 20251115 한 셀의 클래스만 제거 (20251120, 20251125 는 유지)
    target1.removeCellClass("20251115");

    let tmpColor01Count = target1.render.querySelectorAll('.tmpColor01').length;
    let tmpColor02Count = target1.render.querySelectorAll('.tmpColor02').length;

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[removeCellClass('20251115') 후 tmpColor01 적용 셀 개수] " + tmpColor01Count + "개"
        + " / [removeCellClass('20251115') 후 tmpColor02 적용 셀 개수] " + tmpColor02Count + "개"
    );
};
